+import type {SessionCursor} from '../../types/sessionStore.js';

 const MAX_CONTENT_LENGTH = 10000;
+const MAX_SESSION_ID_LENGTH = 128;

 interface ValidationSuccess {
   valid: true;
@@ -30,6 +32,8 @@ export function validateMessage(payload: unknown): ValidationResult {
       return validateUserMessage(message);
     case 'ping':
       return validatePingMessage(message);
+    case 'list_sessions':
+      return validateListSessionsMessage(message);
     default:
       return {valid: false, error: `Unknown message type: ${message.type}`};
   }
@@ -72,3 +76,42 @@ function validatePingMessage(message: Record<string, unknown>): ValidationResult
     },
   };
 }
+
+function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
+  const data: ListSessionsMessage = {type: 'list_sessions'};
+  if (message.limit !== undefined) {
+    if (!isValidLimit(message.limit)) {
+      return {valid: false, error: 'list_sessions limit must be a non-negative integer'};
+    }
+    data.limit = message.limit;
+  }
+  if (message.before !== undefined) {
+    const before = parseBeforeCursor(message.before);
+    if (!before) {
+      return {valid: false, error: 'list_sessions before must be a valid session cursor'};
+    }
+    data.before = before;
+  }
+  return {valid: true, data};
+}
+
+function isValidLimit(limit: unknown): limit is number {
+  return typeof limit === 'number' && Number.isInteger(limit) && limit >= 0;
+}
+
+function parseBeforeCursor(before: unknown): SessionCursor | undefined {
+  if (typeof before !== 'object' || before === null) return undefined;
+  const cursor = before as Record<string, unknown>;
+  if (!isValidSessionId(cursor.sessionId)) return undefined;
+  if (!isValidUpdatedAt(cursor.updatedAt)) return undefined;
+  return {updatedAt: cursor.updatedAt, sessionId: cursor.sessionId};
+}
+
+function isValidSessionId(sessionId: unknown): sessionId is string {
+  return typeof sessionId === 'string' && sessionId.length >= 1 && sessionId.length <= MAX_SESSION_ID_LENGTH;
+}
+
+function isValidUpdatedAt(updatedAt: unknown): updatedAt is string | number {
+  if (typeof updatedAt !== 'string' && typeof updatedAt !== 'number') return false;
+  return Number.isFinite(new Date(updatedAt).getTime());
+}
